import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"42. File Pointers and fopen / fclose","description":"The Little Book of C — 42. File Pointers and fopen / fclose","frontmatter":{"title":"42. File Pointers and fopen / fclose","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 42. File Pointers and fopen / fclose","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":42,"sidebarWeight":42,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose.md","filePath":"posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose.md"};function o(p,e,l,d,r,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose)</p><p>Files let your C programs remember things beyond runtime. Unlike standard input and output, which disappear when the program ends, files provide persistent storage, you can read and write data between runs.</p><p>This section introduces the key file-handling API in C:<code>fopen()</code>,<code>fclose()</code>,<code>fprintf()</code>,<code>fscanf()</code>, and their relatives.</p><h4 id="the-big-picture" tabindex="-1">The Big Picture <a class="header-anchor" href="#the-big-picture" aria-label="Permalink to &quot;The Big Picture&quot;">​</a></h4><p>File I/O in C uses a<code>FILE *</code> pointer to represent an open file. You don’t manipulate the disk directly, instead, you read and write through a buffered file stream managed by the runtime.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *fp = fopen(&quot;data.txt&quot;, &quot;r&quot;);</span></span></code></pre></div><p>This returns a pointer to a<code>FILE</code> object if successful, or<code>NULL</code> if the file can’t be opened.</p><h4 id="file-modes" tabindex="-1">File Modes <a class="header-anchor" href="#file-modes" aria-label="Permalink to &quot;File Modes&quot;">​</a></h4><p>When opening a file, you specify a mode, what you intend to do with it.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Meaning</th><th>Behavior</th></tr></thead><tbody><tr><td><code>&quot;r&quot;</code></td><td>read</td><td>Fails if file doesn’t exist</td></tr><tr><td><code>&quot;w&quot;</code></td><td>write</td><td>Creates new or truncates existing</td></tr><tr><td><code>&quot;a&quot;</code></td><td>append</td><td>Opens or creates; writes go to end</td></tr><tr><td><code>&quot;r+&quot;</code></td><td>read/write</td><td>Must exist</td></tr><tr><td><code>&quot;w+&quot;</code></td><td>read/write</td><td>Truncates if exists</td></tr><tr><td><code>&quot;a+&quot;</code></td><td>read/write</td><td>Appends; reading starts at beginning</td></tr></tbody></table><h4 id="tiny-code-write-and-read-a-file" tabindex="-1">Tiny Code: Write and Read a File <a class="header-anchor" href="#tiny-code-write-and-read-a-file" aria-label="Permalink to &quot;Tiny Code: Write and Read a File&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;example.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fprintf(fp, &quot;Hello, file world!\\n&quot;);</span></span>
<span class="line"><span>    fprintf(fp, &quot;C makes you closer to the machine.\\n&quot;);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    fp = fopen(&quot;example.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to reopen file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;--- File Content ---\\n&quot;);</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, line);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--- File Content ---</span></span>
<span class="line"><span>Hello, file world!</span></span>
<span class="line"><span>C makes you closer to the machine.</span></span></code></pre></div><h4 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h4><ol><li><code>fopen()</code> creates a connection to a file.</li><li><code>fprintf()</code> writes formatted text, just like<code>printf()</code> but to a file stream.</li><li><code>fclose()</code> flushes buffers and closes the file.</li><li>Reopen with<code>&quot;r&quot;</code> mode to read what you wrote.</li></ol><p>You can also mix with<code>fscanf()</code> to read formatted data.</p><h4 id="checking-for-errors" tabindex="-1">Checking for Errors <a class="header-anchor" href="#checking-for-errors" aria-label="Permalink to &quot;Checking for Errors&quot;">​</a></h4><p>Always check file operations for errors. Use<code>if (!fp)</code> after<code>fopen()</code>, and use<code>perror()</code> to print the reason.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;missing.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    perror(&quot;Error opening file&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error opening file: No such file or directory</span></span></code></pre></div><h4 id="reading-formatted-data-with-fscanf" tabindex="-1">Reading Formatted Data with fscanf <a class="header-anchor" href="#reading-formatted-data-with-fscanf" aria-label="Permalink to &quot;Reading Formatted Data with fscanf&quot;">​</a></h4><p>You can parse text files using<code>fscanf()</code>, just like<code>scanf()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;numbers.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) return 1;</span></span>
<span class="line"><span>    int a, b;</span></span>
<span class="line"><span>    while (fscanf(fp, &quot;%d %d&quot;, &amp;a, &amp;b) == 2)</span></span>
<span class="line"><span>        printf(&quot;%d + %d = %d\\n&quot;, a, b, a + b);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If<code>numbers.txt</code> contains:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 3</span></span>
<span class="line"><span>10 15</span></span>
<span class="line"><span>7 9</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 + 3 = 5</span></span>
<span class="line"><span>10 + 15 = 25</span></span>
<span class="line"><span>7 + 9 = 16</span></span></code></pre></div><h4 id="file-position-and-rewinding" tabindex="-1">File Position and Rewinding <a class="header-anchor" href="#file-position-and-rewinding" aria-label="Permalink to &quot;File Position and Rewinding&quot;">​</a></h4><p>You can move around a file using:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fseek(fp, 0, SEEK_SET);  // go to beginning</span></span>
<span class="line"><span>fseek(fp, 0, SEEK_END);  // go to end</span></span>
<span class="line"><span>rewind(fp);              // reset to start</span></span></code></pre></div><p>To know where you are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>long pos = ftell(fp);</span></span>
<span class="line"><span>printf(&quot;Current position: %ld\\n&quot;, pos);</span></span></code></pre></div><h4 id="writing-binary-data" tabindex="-1">Writing Binary Data <a class="header-anchor" href="#writing-binary-data" aria-label="Permalink to &quot;Writing Binary Data&quot;">​</a></h4><p>Text files are human-readable; binary files store raw bytes. You’ll use<code>fwrite()</code> and<code>fread()</code> for that (covered more in the next section).</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int numbers[] = {1, 2, 3, 4};</span></span>
<span class="line"><span>fwrite(numbers, sizeof(int), 4, fp);</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>File I/O is the bridge between your C program and the real world:</p><ul><li>Configuration and log files</li><li>Database storage</li><li>Caches and serialization</li><li>Operating system utilities (copy, move, grep, etc.)</li></ul><p>It teaches resource management, always<code>fopen()</code> and<code>fclose()</code> in pairs, check errors, and handle failures gracefully.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that asks for your name and saves it to<code>user.txt</code>.</li><li>Append a timestamp each time the program runs.</li><li>Read all lines and count how many times your program has been executed.</li><li>Modify the example to reverse all lines read from a file.</li><li>Handle missing files gracefully using<code>perror()</code>.</li></ol><p>You now know how to open, read, and write text files safely. Next, you’ll go deeper into binary files, where data moves in raw bytes, perfect for storing structs and arrays efficiently.</p>`,45)])])}const f=a(i,[["render",o]]);export{h as __pageData,f as default};
